symbols.code_preview:
@dataclass
class RenderedDiagram:
    """Result of diagram rendering."""
    success: bool
    render_method: DiagramRenderMethod
    ...

@dataclass
class DiagramSpec:
    """Specification for a diagram to render."""
    id: str
    title: str
    ...

@dataclass
class MapRegion:
    """A highlighted region/area on the map."""
    points: List[Tuple[float, float]]  # Polygon vertices (lat, lon)
    label: str
    ...

@dataclass
class RenderedMap:
    """Result of map rendering."""
    success: bool
    render_method: MapRenderMethod
    ...

@dataclass
class MapSpec:
    """Specification for a map to generate."""
    id: str
    title: str
    ...

@dataclass
class MapRoute:
    """A route/path on the map."""
    points: List[Tuple[float, float]]  # List of (lat, lon) pairs
    label: str
    ...

@dataclass
class ImageAssetInfo:
    """Information about an image asset from UMCF."""
    id: str
    url: Optional[str]
    ...

@dataclass
class MapMarker:
    """A marker/pin on the map."""
    latitude: float
    longitude: float
    ...

@dataclass
class AcquiredImage:
    """Result of image acquisition."""
    success: bool
    source_type: ImageSourceType
    ...

@dataclass
class FormulaSpec:
    """Specification for a formula to render."""
    id: str
    latex: str
    ...

@dataclass
class MediaGenerationConfig:
    """Configuration for media generation during import."""
    generate_maps: bool = True
    generate_diagrams: bool = True
    ...

@dataclass
class RenderedFormula:
    """Result of formula rendering."""
    success: bool
    render_method: FormulaRenderMethod
    ...

@dataclass
class GeneratedMedia:
    """Result of generating a single media item."""
    id: str
    media_type: str  # map, diagram, formula
    ...

@dataclass
class MediaGenerationStats:
    """Statistics from media generation run."""
    maps_processed: int = 0
    maps_succeeded: int = 0
    ...
